async function call(role,t,prompt,items){return await agent(prompt,{brief:role+' — '+t.brief,input_files:files(items),sandbox:'shared',effort_level:'standard',schema});}
async function runTask(t){
 log('Début : '+t.brief);
 const impl=await call('Implémenter',t,`Rôle implémenteur. ${constraints}\n\n${t.spec}\n\nTDD rouge d’abord; limite les modifications aux fichiers autorisés, exécute les tests ciblés et rapporte les commandes/résultats. Aucun Git, secret, migration réelle ou déploiement. En cas de blocage environnemental, rapporte-le sans le contourner. Retourne un JSON schema-conforme avec role,task,verdict,summary,files_changed,tests_run,findings,blockers.`,t.impl);
 if(!impl.ok||impl.value.verdict!=='completed') return {task:t.id,status:'blocked',implementer:impl.ok?impl.value:impl.error};
 const reviewPrompt=`Reviewer indépendant de conformité. ${constraints}\n\n${t.spec}\n\nInspecte réellement le code et tests reçus, ne crois pas le rapport implémenteur. Aucun changement de fichier. Verdict approved seulement sans omission importante/défaut sécurité; sinon changes_requested. Cite fichiers/lignes. JSON conforme.`;
 let spec=await call('Revue conformité',t,reviewPrompt,t.review);
 if(!spec.ok) return {task:t.id,status:'blocked',implementer:impl.value,spec_review:spec.error};
 if(spec.value.verdict!=='approved'){
  const fix=await call('Corriger conformité',t,`Agent correcteur. ${constraints}\nSpécification:\n${t.spec}\nRapport impl:${JSON.stringify(impl.value)}\nRevue conformité:${JSON.stringify(spec.value)}\nCorrige seulement les constats importants, test rouge puis vert, périmètre autorisé, aucun Git. Retourne JSON conforme.`,t.review);
  if(!fix.ok||fix.value.verdict!=='completed') return {task:t.id,status:'blocked',implementer:impl.value,spec_review:spec.value,fix:fix.ok?fix.value:fix.error};
  spec=await call('Revue conformité après correction',t,`Réévalue réellement le code corrigé selon la spécification suivante: ${t.spec}\nRapport fix:${JSON.stringify(fix.value)}\n${constraints}\nAucun changement. Verdict approved seulement si conforme; JSON conforme.`,t.review);
  if(!spec.ok||spec.value.verdict!=='approved') return {task:t.id,status:'blocked',implementer:impl.value,spec_review:spec.ok?spec.value:spec.error};
 }
 let quality=await call('Revue qualité/sécurité',t,`Reviewer indépendant qualité/sécurité. ${constraints}\nExigences:\n${t.spec}\nInspecte vrai code/tests: sécurité, bugs, cycle de vie, erreurs, accessibilité, robustesse. Aucun changement. Ne bloque que problème important/critique. Cite fichier/ligne. JSON conforme.`,t.review);
 if(!quality.ok) return {task:t.id,status:'blocked',implementer:impl.value,spec_review:spec.value,quality_review:quality.error};
 if(quality.value.verdict!=='approved'){
  const fix=await call('Corriger qualité/sécurité',t,`Agent correcteur. ${constraints}\nSpécification:${t.spec}\nRapport impl:${JSON.stringify(impl.value)}\nRevue qualité:${JSON.stringify(quality.value)}\nCorrige seulement défauts importants/critique, tests d’abord, pas de Git/dépendance nouvelle. JSON conforme.`,t.review);
  if(!fix.ok||fix.value.verdict!=='completed') return {task:t.id,status:'blocked',implementer:impl.value,spec_review:spec.value,quality_review:quality.value,fix:fix.ok?fix.value:fix.error};
  quality=await call('Revue qualité après correction',t,`Revue indépendante, relis code corrigé et confirme les constats. ${constraints}\nExigences:${t.spec}\nAncienne revue:${JSON.stringify(quality.value)}\nCorrection:${JSON.stringify(fix.value)}\nAucun changement; verdict approved seulement sans défaut important. JSON conforme.`,t.review);
  if(!quality.ok||quality.value.verdict!=='approved') return {task:t.id,status:'blocked',implementer:impl.value,spec_review:spec.value,quality_review:quality.ok?quality.value:quality.error};
 }
 log('Lot approuvé par revue conformité et qualité : '+t.brief);
 return {task:t.id,status:'completed',implementer:impl.value,spec_review:spec.value,quality_review:quality.value};
}
const results=[];
for(const t of tasks){const r=await runTask(t);results.push(r);if(r.status!=='completed'){log('Arrêt conservateur sur '+t.id);return {status:'blocked',results};}}
